"<PROGRAM_FILES>\\POWERS~1\\7\\pwsh.exe" -Command '$ErrorActionPreference = '"'Stop'
"'$baseline = [ordered]@{}
Get-ChildItem -Recurse -File | Sort-Object FullName | ForEach-Object {
    $relative = [IO.Path]::GetRelativePath((Get-Location).Path, $_.FullName).Replace('"'\\', '/')
    "'$baseline[$relative] = (Get-FileHash -LiteralPath $_.FullName -Algorithm SHA256).Hash.ToLowerInvariant()
}
Write-Output ('"'HANDOFF_BASELINE=' + ("'$baseline | ConvertTo-Json -Compress))'

"<PROGRAM_FILES>\\POWERS~1\\7\\pwsh.exe" -Command '$ErrorActionPreference = '"'Stop'
"'$draftSource = [IO.Path]::GetFullPath((Join-Path (Get-Location).Path '"'draft-summary.md'))
"'$draftArchive = [IO.Path]::GetFullPath((Join-Path (Get-Location).Path '"'handoff/original-summary.md'))
[IO.File]::Copy("'$draftSource, $draftArchive, $false)
$methodsText = Get-Content -Raw -LiteralPath handoff/methods.md
$reproductionBlock = [regex]::Match($methodsText, '"'(?s)"'```powershell'"\\r?\\n(.*?)\\r?\\n"'```'"')
if (-not "'$reproductionBlock.Success) { throw '"'No reproduction block found.' }
. ([scriptblock]::Create("'$reproductionBlock.Groups[1].Value))
$recordedMetrics = Get-Content -Raw -LiteralPath audit/metrics.json | ConvertFrom-Json -AsHashtable
if ($metrics.Count -ne $recordedMetrics.Count) { throw '"'Reproduced JSON has wrong field count.' }
foreach ("'$key in $recordedMetrics.Keys) {
    if (-not $metrics.Contains($key)) { throw ('"'Missing reproduced field: ' + "'$key) }
    if ([decimal]$metrics[$key] -ne [decimal]$recordedMetrics[$key]) { throw ('"'Reproduction mismatch: ' + "'$key) }
}
if ([Math]::Round($percent, 1) -ne [decimal]12.1) { throw '"'Percentage mismatch.' }
if (@("'$matched.pair_id) -join '"',' -ne 'P1,P2,P3,P4,P5,P6,P8') { throw 'Incorrect eligible pair IDs.' }
Write-Output 'Handoff reproduction: exact fenced PowerShell block executed; all ten fields and eligibility match audit/metrics.json.'
Write-Output ('Archive SHA256: ' + (Get-FileHash -LiteralPath handoff/original-summary.md -Algorithm SHA256).Hash.ToLowerInvariant())"

"<PROGRAM_FILES>\\POWERS~1\\7\\pwsh.exe" -Command "@'

'use strict';
const fs=require('node:fs'),path=require('node:path'),crypto=require('node:crypto'),assert=require('node:assert/strict');
const root=process.cwd(),baseline={\"audit/findings.md\":\"598d74498c057282306127f82348643e35b1d309444cf2dbe995d103f8431784\",\"audit/metrics.json\":\"40faf769f01c0621edf17d1bad82a51b62772c6204cd7b2aab2dccfcd409f58f\",\"draft-summary.md\":\"4a7277ebee0f9597a1e066107380540c66590c6b81304218c91dc46cfd2135d4\",\"evidence/capture-notes.md\":\"e3a2c31c98402958d8c53a8a46279d64925299670c8ec39fac793fa487c43448\",\"evidence/guide.csv\":\"bfbb16f5ea6ab33ef26d7cf47125b375d0459e64cc83e628172d95aade87107a\",\"evidence/pairs.csv\":\"6c0bf3fa53e2fb5e1f8509ad21733b01fbda7a39511f7e55343a269bea5dce74\",\"evidence/reference.csv\":\"91109c551fa1fd29a6e5e59b8085a09b6581b2760f5adbca670f799d99818670\",\"guides/reference-card.txt\":\"236e2c9c478661eea6c9c5466c1ed7160ae1c283598e3468cd83e8a1decb5492\",\"guides/reorganized-guide.txt\":\"94acd3cebd66adbe2aeb94e53163fbde33656d8d7abb28b82c270f2219077fe5\",\"README.md\":\"8a4e73f42045a1670b8d856777664315f7acbc3c4c31739958377e0273fdf732\",\"study/protocol.md\":\"88e3dcebfadee2fcad57fe4777271851501b59587c97c66263ce6be7723a3a3e\",\"tools/check-evidence.cjs\":\"e149be4444c995be3d61b54fea91913d89025aaeaff962ffea5177ba8ac83e5f\"};
for(const [name,hash] of Object.entries(baseline)) assert.equal(crypto.createHash('sha256').update(fs.readFileSync(path.join(root,name))).digest('hex'),hash,name+' changed');
const source=fs.readFileSync('draft-summary.md');
const archive=fs.readFileSync('handoff/original-summary.md');
assert.ok(source.equals(archive),'Archive differs at byte level');
function files(dir){return fs.readdirSync(dir,{withFileTypes:true}).flatMap(entry=>{const full=path.join(dir,entry.name);return entry.isDirectory()?files(full):[path.relative(root,full).split(path.sep).join('/')];});}
assert.deepEqual(files(root).sort(),[...Object.keys(baseline),'handoff/methods.md','handoff/original-summary.md'].sort());
const methods=fs.readFileSync('handoff/methods.md','utf8');
let linkCount=0;
for(const match of methods.matchAll(/\\]\\((["'^)]+)'"\\)/g)){
  const target=path.resolve(root,'handoff',match[1]);
  assert.ok(target.startsWith(root+path.sep));
  assert.ok(fs.existsSync(target),'Broken link '+match[1]);
  linkCount++;
}
function csv(name){const [header,...lines]=fs.readFileSync(name,'utf8').trimEnd().split(/\\r?\\n/);const keys=header.split(',');return lines.map(line=>Object.fromEntries(line.split(',').map((value,i)=>[keys[i],value])));}
const pairs=csv('evidence/pairs.csv'),reference=csv('evidence/reference.csv'),guide=csv('evidence/guide.csv');
const r=new Map(reference.map(row=>[row.pair_id,row])),g=new Map(guide.map(row=>[row.pair_id,row]));
assert.deepEqual(r.get('P5'),{pair_id:'P5',seconds:'140',correct:'true',assisted:'false'});
assert.deepEqual(g.get('P5'),{pair_id:'P5',seconds:'150',correct:'false',assisted:'true'});
assert.deepEqual(r.get('P7'),{pair_id:'P7',seconds:'150',correct:'true',assisted:'false'});
assert.deepEqual(g.get('P7'),{pair_id:'P7',seconds:'',correct:'true',assisted:'true'});
assert.equal(pairs.find(row=>row.pair_id==='P5').volunteer_id,'V3');
assert.equal(pairs.find(row=>row.pair_id==='P7').volunteer_id,'V4');
assert.equal(pairs.find(row=>row.pair_id==='P5').first_format,'reference');
assert.equal(pairs.find(row=>row.pair_id==='P7').first_format,'reference');
for(const volunteer of new Set(pairs.map(row=>row.volunteer_id))) assert.deepEqual(pairs.filter(row=>row.volunteer_id===volunteer).map(row=>row.first_format).sort(),['guide','reference']);
const accuracy=[0,0,0,0];
for(const pair of pairs){const rc=r.get(pair.pair_id).correct==='true',gc=g.get(pair.pair_id).correct==='true';accuracy[rc?(gc?0:2):(gc?1:3)]++;}
assert.deepEqual(accuracy,[6,1,1,0]);
assert.ok(methods.includes('## P5:'));
assert.ok(methods.includes('## P7:'));
assert.ok(methods.includes('## Committee message to copy, not sent'));
assert.ok(methods.includes('at most two staffed sessions with up to six volunteers and four fresh lookups per person'));
process.stdout.write(JSON.stringify({status:'passed',pre_existing_files_unchanged:Object.keys(baseline).length,archive_identical_bytes:archive.length,archive_sha256:crypto.createHash('sha256').update(archive).digest('hex'),local_links_checked:linkCount,case_examples_and_accuracy:'match source records',only_added_files:['handoff/methods.md','handoff/original-summary.md']},null,2)+'\\n');

'@ | node -"
